const ALL_SKILL_ART_ICONS: SkillArtIcon[] = SKILL_ART_CATEGORIES.flatMap(cat => [
    ...cat.icons,
    ...cat.subcategories.flatMap(sub => [
        ...sub.icons,
        ...sub.groups.flatMap(grp => grp.icons),
    ]),
]);
export function searchSkillArt(query: string): SkillArtIcon[] {
    const q = query.toLowerCase();
    return ALL_SKILL_ART_ICONS.filter(icon => icon.label.toLowerCase().includes(q) || icon.id.toLowerCase().includes(q));
}
